def SidonProp (s : Finset ℕ) : Prop :=
  ∀ (a b c d : ℕ), a ∈ s → b ∈ s → c ∈ s → d ∈ s →
    a + b = c + d → (a = c ∧ b = d) ∨ (a = d ∧ b = c)

def sidonGood (s : Finset ℕ) (m : ℕ) : Prop := SidonProp (insert m s)

def nextGreedy (s : Finset ℕ) : ℕ :=
  s.sup + 1 +
    Nat.findGreatest
      (fun (j : ℕ) => ∀ (i : ℕ), i ∈ Finset.Icc 1 j → sidonGood s (s.sup + 1 + i))
      ((s.sup + 3) ^ 3)
  + 1

def greedySet : ℕ → Finset ℕ
  | 0 => {1}
  | (n + 1) => insert (nextGreedy (greedySet n)) (greedySet n)

def memSidon (n : ℕ) : Prop := ∃ (k : Fin (n + 1)), n ∈ greedySet (k : ℕ)

def sidonCount (N : ℕ) : ℕ :=
  (Finset.Icc 1 N).filter (fun (n : ℕ) => memSidon n) |>.card

